def nextstate(q, x):
	i = 0
	for i in range(len(q)):
		if q[i] & x > 0:
			return q[:i] + (x,) + q[i + 1:]
	return q + (x,)
qs = [()]
trans = []
ptr = 0
while ptr < len(qs):
	q = qs[ptr]
	tb = []
	for x in range(1, 4):
		qn = nextstate(q, x)
		if qn not in qs:
			qs.append(qn)
		tb.append(qs.index(qn))
	trans.append(tb)
	ptr += 1
n = int(input())
a = [int(x) for x in input().split(' ')]
cnt = [0] * len(qs)
cnt[0] = 1
ans = 0
for (i, ai) in enumerate(a):
	cnt2 = [0] * len(qs)
	cnt2[0] = 1
	if ai == 0:
		for j in range(len(qs)):
			cnt2[j] += cnt[j]
		ans += (i + 1) * (n - i)
	else:
		for j in range(len(qs)):
			qn = trans[j][ai - 1]
			cnt2[qn] += cnt[j]
	for j in range(len(qs)):
		ans += cnt2[j] * len(qs[j])
	cnt = cnt2
print(ans)
